namespace Workplace.Data.Entities;

public static class EmploymentStatuses
{
    public const string Active = "active";
    public const string OnLeave = "on_leave";
    public const string Terminated = "terminated";
}

public class Employee
{
    public Guid Id { get; set; }
    public string EmployeeNumber { get; set; } = "";
    public string FirstName { get; set; } = "";
    public string LastName { get; set; } = "";

    /// <summary>Generated by the database (first_name || ' ' || last_name).</summary>
    public string FullName { get; set; } = "";

    public string Email { get; set; } = "";
    public string JobTitle { get; set; } = "";

    public Guid SiteId { get; set; }
    public Guid DepartmentId { get; set; }
    public Guid? ManagerId { get; set; }

    public string EmploymentStatus { get; set; } = EmploymentStatuses.Active;
    public DateOnly? HireDate { get; set; }
    public DateOnly? TerminationDate { get; set; }

    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow;

    public Site Site { get; set; } = null!;
    public Department Department { get; set; } = null!;
    public Employee? Manager { get; set; }
    public List<EmployeeShiftAssignment> ShiftAssignments { get; set; } = [];
}

public class EmployeeShiftAssignment
{
    public Guid Id { get; set; }
    public Guid EmployeeId { get; set; }
    public Guid ShiftId { get; set; }
    public DateOnly EffectiveFrom { get; set; }

    /// <summary>NULL means this is the current assignment.</summary>
    public DateOnly? EffectiveTo { get; set; }

    public Employee Employee { get; set; } = null!;
    public Shift Shift { get; set; } = null!;
}
